use crate::fonts::KatexFont;

/// Every face has 1000 units per em.
pub const UNITS_PER_EM: u16 = 1000;

/// `(code point, advance)` pairs, sorted by code point (2195 entries over the 20 faces).
pub fn advances(font: KatexFont) -> &'static [(u32, u16)] {
    match font {
        KatexFont::AmsRegular => AMS_REGULAR,
        KatexFont::CaligraphicBold => CALIGRAPHIC_BOLD,
        KatexFont::CaligraphicRegular => CALIGRAPHIC_REGULAR,
        KatexFont::FrakturBold => FRAKTUR_BOLD,
        KatexFont::FrakturRegular => FRAKTUR_REGULAR,
        KatexFont::MainBold => MAIN_BOLD,
        KatexFont::MainBoldItalic => MAIN_BOLD_ITALIC,
        KatexFont::MainItalic => MAIN_ITALIC,
        KatexFont::MainRegular => MAIN_REGULAR,
        KatexFont::MathBoldItalic => MATH_BOLD_ITALIC,
        KatexFont::MathItalic => MATH_ITALIC,
        KatexFont::SansSerifBold => SANS_SERIF_BOLD,
        KatexFont::SansSerifItalic => SANS_SERIF_ITALIC,
        KatexFont::SansSerifRegular => SANS_SERIF_REGULAR,
        KatexFont::ScriptRegular => SCRIPT_REGULAR,
        KatexFont::Size1Regular => SIZE1REGULAR,
        KatexFont::Size2Regular => SIZE2REGULAR,
        KatexFont::Size3Regular => SIZE3REGULAR,
        KatexFont::Size4Regular => SIZE4REGULAR,
        KatexFont::TypewriterRegular => TYPEWRITER_REGULAR,
    }
}

/// The advance of `c` in `font` (font units), or `None` if the face does not map it (the
/// browser then falls back to another font).
pub fn advance(font: KatexFont, c: char) -> Option<u16> {
    let t = advances(font);
    t.binary_search_by(|(k, _)| k.cmp(&(c as u32)))
        .ok()
        .map(|i| t[i].1)
}

